def suggest_dosage(data: dict) -> str:
    # Check if the patient is a woman
    if data.get('gender', '').lower() == 'female':
        return '0'

    # Extract relevant patient information
    age = data.get('age', 0)
    stress_level = data.get('stress_level', 0)
    occupation = data.get('occupation', '').lower()

    # Basic dosage recommendation logic
    if age < 18:
        return '50 mg'
    elif age <= 65:
        if stress_level > 7:
            return '100 mg'
        elif stress_level > 4:
            return '75 mg'
        else:
            return '50 mg'
    else:
        return '25 mg'  # For patients over 65

